<?php declare(strict_types=1);
$ccFields=['documents'=>'document_id','contacts'=>'contact_id','events'=>'event_id'];$ccChoiceLabels=['documents'=>'Vorhandene Datei auswählen','contacts'=>'Person / Mitglied (optional)','events'=>'Veranstaltung (optional)'];$ccField=$ccFields[$ccSource];$ccChoices=$ccState['sources'][$ccSource]??null;$ccSelection=$ccState['selected'][$ccSource]??null;$ccUnavailable=$ccState['selected'][$ccSource.'_unavailable']??false;$ccChoiceState=$ccForm['sources'][$ccSource];
?>
<details class="check-choice" data-check-choice="<?= e($ccSource) ?>" <?= str_starts_with($ccForm['browse'],$ccSource.':')||isset($ccState['source_errors'][$ccSource])?'open':'' ?>><summary><?= e($ccI($ccChoiceLabels[$ccSource])) ?></summary><fieldset><legend><?= e($ccI($ccChoiceLabels[$ccSource])) ?></legend>
<?= hidden($ccField,$ccData[$ccField]) ?>
<p data-check-selected="<?= e($ccSource) ?>"><?= e($ccI('Gewählte Zuordnung')) ?>: <?php if($ccSelection!==null):?><?= e($ccSelection[$ccSource==='contacts'?'name':'title']) ?><?php elseif($ccData[$ccField]!==''):?><?= e($ccI($ccUnavailable?'Gewählte Zuordnung derzeit nicht verfügbar.':'Vorhandene Zuordnung beibehalten')) ?><?php else:?><?= e($ccI('Keine Zuordnung / für den Verein')) ?><?php endif ?></p>
<?php if($ccSource==='documents'&&$ccSelection!==null):?><p><a href="?view=documents&amp;doc=<?= e(rawurlencode($ccData[$ccField])) ?>"><?= e($ccI('Zugeordnete Datei öffnen')) ?></a></p><?php endif ?>
<label><?= e($ccI('In dieser Auswahl suchen')) ?><input class="form-control" type="search" name="check_query_<?= e($ccSource) ?>" value="<?= e($ccChoiceState['query']) ?>" data-check-choice-query="<?= e($ccSource) ?>"></label>
<div class="dwf-actions"><button class="btn btn-outline theme-secondary dwf-button" type="submit" name="check_pick" value="<?= e($ccSource) ?>:search" formnovalidate><?= e($ccI('Suche anwenden')) ?></button><button class="btn btn-outline theme-secondary dwf-button" type="submit" name="check_pick" value="<?= e($ccSource) ?>:clear" formnovalidate><?= e($ccI('Zuordnung entfernen und Suche leeren')) ?></button></div>
<?php if($ccSource==='events'):?><?= hidden('check_event_archive','0') ?><label class="dwf-check"><input class="check" type="checkbox" name="check_event_archive" value="1" <?= $ccForm['event_archive']?'checked':'' ?>><span><?= e($ccI('Vergangene Veranstaltungen')) ?></span></label><button class="btn btn-outline theme-secondary dwf-button" type="submit" name="check_pick" value="events:refresh" formnovalidate><?= e($ccI('Zeitraum anwenden')) ?></button><?php endif ?>
<?php if(isset($ccState['source_errors'][$ccSource])):?><p class="dwf-alert dwf-error" role="alert"><?= e($ccI($ccState['source_errors'][$ccSource])) ?></p><?php endif ?>
<?php if($ccChoices!==null):?><p role="status"><?= e($ccF('{count} Einträge · Seite {page} von {pages}',['count'=>$ccChoices['total'],'page'=>$ccChoices['page'],'pages'=>$ccChoices['pages']])) ?></p><div class="check-choice-options"><?php foreach($ccChoices['rows']as$ccChoice):?><label class="dwf-check"><input class="check" type="radio" name="<?= e($ccField) ?>" value="<?= e($ccChoice['id']) ?>" <?= $ccData[$ccField]===$ccChoice['id']?'checked':'' ?>><span><?= e($ccChoice[$ccSource==='contacts'?'name':'title']) ?><?php if($ccSource==='events'):?> · <?= e($ccDate((new DateTimeImmutable($ccChoice['starts_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('Y-m-d'))) ?><?php endif ?></span></label><?php endforeach ?></div><?php if(!$ccChoices['rows']):?><p><?= e($ccI('Keine passenden Einträge.')) ?></p><?php endif ?><?php endif ?>
<nav class="dwf-actions" aria-label="<?= e($ccI($ccChoiceLabels[$ccSource])) ?>"><button class="btn btn-outline theme-secondary dwf-button" type="submit" name="check_pick" value="<?= e($ccSource) ?>:previous" formnovalidate <?= $ccChoices!==null&&$ccChoices['page']===1?'disabled':'' ?>><?= e($ccI('Vorherige Seite')) ?></button><button class="btn btn-outline theme-secondary dwf-button" type="submit" name="check_pick" value="<?= e($ccSource) ?>:next" formnovalidate <?= $ccChoices!==null&&$ccChoices['page']===$ccChoices['pages']?'disabled':'' ?>><?= e($ccI('Nächste Seite')) ?></button><label><?= e($ccI('Seite')) ?><input class="form-control" type="number" min="1" name="check_page_<?= e($ccSource) ?>" value="<?= e($ccChoices['page']??$ccChoiceState['page']) ?>"></label><button class="btn btn-outline theme-secondary dwf-button" type="submit" name="check_pick" value="<?= e($ccSource) ?>:page" formnovalidate><?= e($ccI('Seite öffnen')) ?></button></nav>
